select  from order_profit_ledger opl
LEFT JOIN merchant m ON opl.merchant_id = m.id
LEFT JOIN distributor d ON opl.distributor_id = d.id

    opl.del_flag = '0'
    and opl.merchant_id = #{merchantId}
    and opl.distributor_id = #{distributorId}
    and opl.order_no = #{orderNo}
    and opl.status = #{status}

order by opl.create_time desc

